 482→async function importDocumentsPackagesFields(req, res) {
 483→
 484→    if (!req.file) {
 485→        return res.status(400).send({
 486→          status: false,
 487→          message: "No se ha subido ningún archivo",
 488→          errors: [
 489→            {
 490→              field_name: "file",
 491→            },
 492→          ],
 493→        });
 494→    }
 495→
 496→    const countryId = req.body.countryId;
 497→
 498→    const file = req.file;
 499→    const workbook = new ExcelJS.Workbook();
 500→
 501→    await workbook.xlsx.readFile(file.path);
 502→
 503→    const worksheet = workbook.getWorksheet(1);
 504→    if (!worksheet) {
 505→        return res.status(400).send({
 506→            status: false,
 507→            message: "El archivo no contiene hojas válidas.",
 508→            errors: [{ field_name: "file" }],
 509→        });
 510→    }
 511→        
 512→    let hasData = false;
 513→    worksheet.eachRow((row, rowNumber) => {
 514→        if (rowNumber > 1) {
 515→            let rowHasRealData = false;
 516→    
 517→            row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
 518→                if (cell.value !== null && cell.value !== '' && typeof cell.value !== 'object') {
 519→                    rowHasRealData = true;
 520→                }
 521→            });
 522→    
 523→            if (rowHasRealData) {
 524→                hasData = true;
 525→            } else {
 526→                console.log(`Fila ${rowNumber} solo contiene validaciones o está vacía.`);
 527→            }
 528→        }
 529→    });
 530→    
 531→    if (!hasData) {
 532→        return res.status(400).send({
 533→            status: false,
 534→            message: "El archivo está vacío o solo contiene validaciones de datos sin valores.",
 535→            errors: [{ field_name: "file" }],
 536→        });
 537→    }
 538→
 539→    try {
 540→        const documentTypes = await db.identification_types.findMany({
 541→            where: {
 542→                country_id: parseInt(countryId),
 543→            },
 544→            select: {
 545→                id: true,
 546→                name: true,
 547→                field_type: true,
 548→            }
 549→        });
 550→
 551→        const documentTypeMap = {};
 552→        const documentTypeIdMap = {};
 553→
 554→        documentTypes.forEach(type => {
 555→            documentTypeMap[type.name] = type.field_type;
 556→            documentTypeIdMap[type.name] = type.id;
 557→        });
 558→
 559→       
 560→        let headers = {};
 561→        let fields = [];
 562→        let signers = [];
 563→        let variableHeaders = [];
 564→
 565→        worksheet.getRow(1).eachCell((cell, colNumber) => {
 566→            headers[cell.text] = colNumber;
 567→            if (cell.text.startsWith('Firmante')) {
 568→                signers.push(cell.text);
 569→            } else if (cell.text.startsWith('VAR_')) {
 570→                variableHeaders.push(cell.text);
 571→            } else if (!['Fecha y hora límite para realizar la firma', 'Número de contrato'].includes(cell.text)) {
 572→                fields.push(cell.text);
 573→            }
 574→        });
 575→
 576→        let dataArr = [];
 577→        let errors = []; 
 578→
 579→        const isValidEmail = (email) => {
 580→            return /\S+@\S+\.\S+/.test(email);
 581→        };
 582→
 583→        const isValidPhoneNumber = (phone) => {
 584→            return /^\d{10,14}$/.test(phone);
 585→        };
 586→
 587→
 588→        worksheet.eachRow({ includeEmpty: true }, function(row, rowNumber) {
 589→            if (rowNumber !== 1) { 
 590→
 591→                let isRowEmpty = true;
 592→                row.eachCell({ includeEmpty: true }, function(cell, colNumber) {
 593→                    if (cell.value !== null && cell.value !== '') {
 594→                        isRowEmpty = false;
 595→                    }
 596→                });
 597→
 598→                if (row.actualCellCount === 0 || row.values.every(cell => cell === null || cell === '')) {
 599→                    return;
 600→                }
 601→                
 602→                let errorsRow = [];
 603→
 604→                const expiresInDaysCell = row.getCell(headers['Fecha límite para realizar la firma']);
 605→                const expiresInDays = expiresInDaysCell ? expiresInDaysCell.value : null;
 606→
 607→                let expiresDate;
 608→                if (!expiresInDays) {
 609→                    errorsRow.push(`La fecha en la fila ${rowNumber} no tiene valor.`);
 610→                } else {
 611→                    if (expiresInDays instanceof Date) {
 612→                        expiresDate = expiresInDays;
 613→                    } else if (typeof expiresInDays === 'string' || typeof expiresInDays === 'number') {
 614→                        expiresDate = new Date(expiresInDays);
