15→async function updateContent2(document_package_signer_detail_value_id, fields, fields_values, prisma) {
16→
17→    const tmpFields = fields.split("|");
18→    const tmpFieldsValues = fields_values.split("|");
19→
20→    const documentPackageDetail = await prisma.document_packages_signers_details_values.findFirst({
21→        where: { id: document_package_signer_detail_value_id },
22→        select: { modified_content: true },
23→    });
24→
25→
26→    try {
27→        if (documentPackageDetail) {
28→            let content = documentPackageDetail.modified_content;
29→
30→            for (let i = 0; i < tmpFields.length; i++) {
31→                const valueToReplace = i < tmpFieldsValues.length && tmpFieldsValues[i] != null ? tmpFieldsValues[i] : "";
32→
33→             //   console.log(`Replacing ${tmpFields[i]} with ${valueToReplace}`);
34→                const fieldRegex = new RegExp("{\\s*" + tmpFields[i] + "\\s*}", "g");
35→                content = content.replace(fieldRegex, valueToReplace);
36→            }
37→
38→            const allFieldsInContent = [...content.matchAll(/{\s*([\w\d_]+)\s*}/g)];
39→
40→            for (const match of allFieldsInContent) {
41→                const field = match[1];
42→                if (!tmpFields.includes(field)) {
43→                    const orphanFieldRegex = new RegExp("{\\s*" + field + "\\s*}", "g");
44→                    content = content.replace(orphanFieldRegex, "");
45→                }
46→            }
47→
48→            await prisma.document_packages_signers_details_values.updateMany({
49→                where: { id: parseInt(document_package_signer_detail_value_id) },
50→                data: { modified_content: content },
51→            });
52→        }
53→    } catch (err) {
54→        console.log(err);
55→    }
56→}
