 242→async function getContentFromS3(documentIds, s3Keys) { 
 243→    let contents = {};
 244→    const private_key = fs.readFileSync("./my_key.key", "utf-8");
 245→
 246→    for (let i = 0; i < documentIds.length; i++) {
 247→        try {
 248→            const response = await s3Client.send(new GetObjectCommand({ 
 249→                Bucket: process.env.S3_BUCKET, 
 250→                Key: s3Keys[i]
 251→            }));
 252→
 253→            const token = await response.Body.transformToString('utf-8');
 254→            const decoded = jwt_.verify(token, private_key, { algorithms: ["RS512"] });
 255→            contents[documentIds[i]] = decoded.pdf; 
 256→
 257→        } catch (error) {
 258→            console.error(`Error handling S3 object or JWT for document ID ${documentIds[i]}:`, error);
 259→        }
 260→    }
 261→    return contents;
 262→}
