 278→function findReplaceString(str, find, replace) {
 279→    var escapedFind = find.replace(/([.*+?^=!:${}()|\[\]\/\\])/g, "\\$1");
 280→    return str.replace(new RegExp(escapedFind, "g"), replace);
 281→}
