1610→async function sendGroupEmails(emails, request_id, signedAt, groupName, companyName,  isMultiplePdf = false, pdfBuffers  = null, documentHashes = null) {
1611→    try {
1612→        let transporter = nodemailer.createTransport({
1613→            host: hostmail,
1614→            port: portmail,
1615→            secure: false,
1616→            auth: {
1617→                user: usermail, 
1618→                pass: passmail, 
1619→            },
1620→        });
1621→
1622→        let zipPath = null;
1623→
1624→        let finalPdfBuffers = [];
1625→
1626→        if (!isMultiplePdf) {
1627→            const documents = await fetchDocuments(request_id);
1628→            zipPath = await generatePDFsAndZip(documents, signedAt, request_id);
1629→        } else {
1630→            for (let i = 0; i < pdfBuffers.length; i++) {
1631→                const pdfBuffer = pdfBuffers[i].buffer;
1632→                const document_hash = documentHashes[i]?.document_hash || "SIN_HASH";
1633→
1634→                const pdfDoc = await PDFDocument.load(pdfBuffer);
1635→                const numPages = pdfDoc.getPages().length;
1636→                const lastPage = pdfDoc.getPages()[numPages - 1];
1637→
1638→                const footerText = `ID: ${document_hash}; Completado el: ${moment.utc(signedAt).tz('America/Bogota').format('YYYY-MM-DD HH:mm:ss')}`;
1639→                
1640→                const qrImgValidation = await qr.toDataURL(process.env.URL_CERTICATE_VALIDATION + "?id=" + request_id);
1641→                const qrImage = await pdfDoc.embedPng(Buffer.from(qrImgValidation.split(",")[1], "base64"));
1642→
1643→                pdfDoc.getPages().forEach((page, pageIndex) => {
1644→                    const pageQrArea = {
1645→                        x: page.getWidth() - 80,
1646→                        y: 20,
1647→                        width: 60,
1648→                        height: 60
1649→                    };
1650→
1651→                    if (pageIndex === numPages - 1) {
1652→                        page.drawImage(qrImage, {
1653→                            x: pageQrArea.x - 40,
1654→                            y: pageQrArea.y + 40,
1655→                            width: pageQrArea.width,
1656→                            height: pageQrArea.height,
1657→                        });
1658→
1659→                        page.drawText('Validación certificado', {
1660→                            x: pageQrArea.x - 60,
1661→                            y: pageQrArea.y + 30,
1662→                            size: 9,
1663→                            color: rgb(0, 0, 0),
1664→                        });
1665→                    }
1666→
1667→                    page.drawText(footerText, {
1668→                        x: 20,
1669→                        y: 10,
1670→                        size: 9,
1671→                        color: rgb(0, 0, 0),
1672→                    });
1673→                });
1674→
1675→                const finalPdfBuffer = Buffer.from(await pdfDoc.save());
1676→                finalPdfBuffers.push({ name: pdfBuffers[i].name, buffer: finalPdfBuffer });
1677→            }
1678→        }
1679→
1680→        await Promise.all(
1681→            emails.map(async (email) => {
1682→                await sendEmailWithAttachment(
1683→                    transporter,
1684→                    email,
1685→                    isMultiplePdf ? finalPdfBuffers : zipPath,
1686→                    groupName,
1687→                    companyName,
1688→                    isMultiplePdf
1689→                );
1690→            })
1691→        );
1692→    
1693→    } catch (e) {
1694→        console.error("Error en el envío de correos grupales:", e);
1695→        throw e;
1696→    }
1697→}
