1726→async function generatePDFsAndZip(documents, signedAt, request_id) {
1727→    const zipPath = 'pdfs.zip';
1728→    const archive = archiver('zip', { zlib: { level: 9 } });
1729→    const output = fs.createWriteStream(zipPath);
1730→    archive.pipe(output);
1731→    const private_key = fs.readFileSync("./my_key.key", "utf-8");
1732→    const limit = pLimit(2);
1733→    
1734→    const tasks = documents.map(doc =>
1735→        limit(async () => {
1736→            try {
1737→                const htmlContent = await fetchDocumentContent(private_key, doc.s3_key);
1738→                const pdfBuffer = await generatePDF(htmlContent, doc, signedAt, request_id);
1739→
1740→                if (pdfBuffer && pdfBuffer.length > 0) {
1741→                    archive.append(pdfBuffer, { name: `${doc.name}.pdf` });
1742→                }
1743→            } catch (err) {
1744→                console.error("Error generando PDF para zippear:", err);
1745→            }
1746→        })
1747→    );
1748→
1749→    await Promise.all(tasks);
1750→
1751→    await new Promise((resolve, reject) => {
1752→        output.on('close', resolve);
1753→        archive.on('error', reject);
1754→        archive.finalize();
1755→    });
1756→    return zipPath;
1757→}
