1759→async function fetchDocumentContent(privateKey, key) {
1760→    const s3Params = {
1761→        Bucket: process.env.S3_BUCKET,
1762→        Key: key,
1763→    };
1764→
1765→    const data = await s3Client.send(new GetObjectCommand(s3Params))
1766→    const token = await data.Body.transformToString('utf-8');
1767→    const decoded = jwt_.verify(token, privateKey, { algorithms: ["RS512"] });
1768→    return decoded.pdf;
1769→};
