1771→async function generatePDF(htmlContent, document, signedAt, request_id) {
1772→    const page = await getPage();
1773→    try {
1774→        await page.setContent(htmlContent);
1775→        const options = {
1776→            margin: {
1777→                top: '22mm',  
1778→                right: '19mm',    
1779→                bottom: '22mm',
1780→                left: '19mm',
1781→            },    
1782→            displayHeaderFooter: true,
1783→            printBackground: true
1784→        };
1785→    
1786→        const width = document.document_packages_details.template.custom_width;
1787→        const height = document.document_packages_details.template.custom_height;
1788→    
1789→        const header = document.document_packages_details.template.header_content ? JSON.parse(document.document_packages_details.template.header_content) : null;
1790→        const footer = document.document_packages_details.template.footer_content ? JSON.parse(document.document_packages_details.template.footer_content) : null;
1791→    
1792→        if (width && height) {
1793→            options.width = width + 'cm';
1794→            options.height = height + 'cm';
1795→        } else {
1796→            options.format = document.document_packages_details.template.paper_size || 'Letter';
1797→        }
1798→    
1799→        let pdfBuffer = null;
1800→    
1801→                
1802→        options.displayHeaderFooter = true;
1803→        options.printBackground = true;
1804→    
1805→        options.headerTemplate = generateHeaderTemplate(header ? header : null);
1806→
1807→        const documentInfo = {
1808→            hash: document.document_packages_details.document_hash,
1809→            completionDate: document.document_packages_details.document_hash ? signedAt : null,
1810→        };
1811→
1812→        options.footerTemplate = generateFooterTemplate(footer ? footer : null, documentInfo);
1813→        
1814→        pdfBuffer = await page.pdf(options);
1815→        
1816→        let finalPdfBuffer;
1817→    
1818→        const pdfDoc = await PDFDocument.load(pdfBuffer);
1819→        const numPages = pdfDoc.getPages().length;
1820→        const lastPage = pdfDoc.getPages()[numPages - 1];
1821→    
1822→        const qrArea = {
1823→            x: 480, 
1824→            y: 50,  
1825→            width: 60, 
1826→            height: 60
1827→        };
1828→    
1829→        const isAreaEmpty = true;
1830→    
1831→        if (isAreaEmpty) {
1832→            const qrImgValidation = await qr.toDataURL(process.env.URL_CERTICATE_VALIDATION + "?id=" + request_id);
1833→    
1834→            const qrImage = await pdfDoc.embedPng(Buffer.from(qrImgValidation.split(",")[1], "base64"));
1835→    
1836→            lastPage.drawImage(qrImage, {
1837→                x: qrArea.x,
1838→                y: qrArea.y,
1839→                width: qrArea.width,
1840→                height: qrArea.height
1841→            });
1842→    
1843→            lastPage.drawText('Validación certificado', {
1844→                x: qrArea.x - 15, 
1845→                y: qrArea.y - 15, 
1846→                size: 9,
1847→                color: rgb(0, 0, 0), 
1848→            });
1849→    
1850→            finalPdfBuffer = Buffer.from(await pdfDoc.save());
1851→        }
1852→    
1853→        return finalPdfBuffer;
1854→    } catch (error) {
1855→        console.log(error);
1856→    } finally {
1857→        await releasePage(page);
1858→    }
1859→};
