1923→
1924→
1925→    const cacheKey = companyIds.sort().join("-");
1926→
1927→    if (storageCache[cacheKey] && storageCache[cacheKey].timestamp > Date.now() - 300000) {
1928→        return storageCache[cacheKey].storage;
1929→    }
1930→
1931→    let total = 0;
1932→    for (const id of companyIds) {
