1967→async function calculateStorageUsed(company_id) {
1968→
1969→    const bucketName = process.env.S3_BUCKET_PREFIX;
1970→    const prefixes = [
1971→        `documents/${process.env.BRANCH}/${company_id}/`,
1972→        `stored_files/${company_id}/`
1973→    ]; 
1974→    
1975→    try {
1976→        let totalSize = 0;
1977→
1978→        for (const prefix of prefixes) {
1979→            let continuationToken = null;
1980→            do {
1981→                const params = {
1982→                    Bucket: bucketName,
1983→                    Prefix: prefix,
1984→                    ContinuationToken: continuationToken
1985→                };
1986→
1987→                const response = await s3Client.send(new ListObjectsV2Command(params));
1988→
1989→                response.Contents?.forEach(obj => {
1990→                    totalSize += obj.Size;
1991→                });
1992→
1993→                continuationToken = response.IsTruncated ? response.NextContinuationToken : null;
1994→            } while (continuationToken);
1995→
1996→        }
1997→
1998→        console.log("Información de almacenamiento utilizada:", totalSize / (1024 * 1024 * 1024));
1999→
2000→        return totalSize / (1024 * 1024 * 1024);
2001→
2002→    } catch (error) {
2003→        console.error("Error al calcular el almacenamiento:", error);
2004→        throw error; 
2005→    }
2006→}
