2008→const uploadSignToS3 = async (company_id, document_package_signer_id, signBase64) => {
2009→    if (!signBase64) {
2010→        throw new Error("Firma no proporcionada");
2011→    }
2012→
2013→    const match = signBase64.match(/^data:(.+);base64,(.+)$/);
2014→    if (!match) {
2015→        throw new Error("Formato de firma inválido");
2016→    }
2017→
2018→    const mimeType = match[1];
2019→    const buffer = Buffer.from(match[2], "base64");
2020→
2021→    const extension = mimeType === "image/png" ? "png"
2022→                    : mimeType === "image/jpeg" || mimeType === "image/jpg" ? "jpg"
2023→                    : mimeType === "image/svg+xml" ? "svg"
2024→                    : "bin";
2025→
2026→    const signatureHash = crypto.createHash("sha256").update(buffer).digest("hex");
2027→
2028→    const key = `signatures/${company_id}/${document_package_signer_id}/${signatureHash}.${extension}`;
2029→
2030→    try {
2031→        await s3Client.send(new PutObjectCommand({
2032→            Bucket: BUCKET_NAME,
2033→            Key: key,
2034→            Body: buffer,
2035→            ContentType: mimeType,
2036→        }));
2037→
2038→        
2039→
2040→        const sign_url = buildS3Url(key);
2041→
2042→        return sign_url; 
2043→    } catch (error) {
2044→        console.error(`Error al subir firma para document_signer_id ${document_package_signer_id}:`, error);
2045→        throw error;
2046→    }
2047→};
