2049→function buildS3Url(key) {
2050→  const bucket = process.env.S3_BUCKET_PREFIX;
2051→  const folder = process.env.S3_FOLDER;
2052→
2053→  let path = key;
2054→
2055→  if (folder && folder.trim() !== '') {
2056→    const encodedFolder = encodeURIComponent(folder);
2057→    path = `${encodedFolder}/${key}`;
2058→  }
2059→
2060→  return `https://${bucket}.s3.amazonaws.com/${path}`;
2061→}
